            ld bc, #001F		; Keys.cls 133
            jr z, fn_keys_joystick_kjport		; Keys.cls 134
            ld c, #37		; Keys.cls 135
fn_keys_joystick_kjport:		; Keys.cls 136
            in a, (c)               ; Kempston: bit 0 right, 1 left, 2 down, 3 up, 4 fire 1, 5 fire 2 [137]
            ld c, a		; Keys.cls 138
            ld e, 0		; Keys.cls 139
            rrca		; Keys.cls 140
            jr nc, fn_keys_joystick_kjnr		; Keys.cls 141
            set 3, e                ; right [142]
fn_keys_joystick_kjnr:		; Keys.cls 143
            rrca		; Keys.cls 144
            jr nc, fn_keys_joystick_kjnl		; Keys.cls 145
            set 2, e                ; left [146]
fn_keys_joystick_kjnl:		; Keys.cls 147
            rrca		; Keys.cls 148
            jr nc, fn_keys_joystick_kjnd		; Keys.cls 149
            set 1, e                ; down [150]
fn_keys_joystick_kjnd:		; Keys.cls 151
            rrca		; Keys.cls 152
            jr nc, fn_keys_joystick_kjnu		; Keys.cls 153
            set 0, e                ; up [154]
fn_keys_joystick_kjnu:		; Keys.cls 155
            rrca		; Keys.cls 156
            jr nc, fn_keys_joystick_kjn1		; Keys.cls 157
            set 5, e                ; fire 1 [158]
fn_keys_joystick_kjn1:		; Keys.cls 159
            rrca		; Keys.cls 160
            jr nc, fn_keys_joystick_kjn2		; Keys.cls 161
            set 4, e                ; fire 2 [162]
fn_keys_joystick_kjn2:		; Keys.cls 163
            ld d, 0		; Keys.cls 164
            pop hl		; Keys.cls 165
            ld (hl), e		; Keys.cls 166
            inc hl		; Keys.cls 167
            ld (hl), d		; Keys.cls 168
			ret			; end of #asm


